mapper.select:


    del_flag = '0'

        and config_code like concat('%', #{configCode}, '%')


        and config_name like concat('%', #{configName}, '%')


        and status = #{status}


        and region_code like concat(#{regionCode}, '%')


        and default_region_code = #{defaultRegionCode}

    ${params.regionDataScope}

order by update_time desc, config_id desc
